def transform(grid):
    # Objects are extracted as 4-connected non-background components, then ordered
    # left-to-right. Placement is intentionally provisional pending more examples.
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            cells = {(r, c)}
            seen.add((r, c))
            stack = [(r, c)]
            while stack:
                y, x = stack.pop()
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); cells.add((yy,xx)); stack.append((yy,xx))
            minr=min(y for y,x in cells); minc=min(x for y,x in cells)
            shape={(y-minr,x-minc) for y,x in cells}
            objects.append((minc, color, shape))
    objects.sort()
    # Not yet fitted to the demonstrated diagonal placement rule.
    return [row[:] for row in grid]

